//! The bridge: `aralo-core` as the native shells see it, generated by UniFFI.
//!
//! Two objects cross the bridge. [`Engine`] is the keystroke path: one call per
//! key, one short lock, no file access. [`Core`] is everything else. They share
//! one [`aralo_core::Runtime`], so a match comes back from `on_key` with its
//! plan already built and the shell never makes a second call while a key is
//! waiting.
//!
//! The library is watched and indexed for as long as the [`Core`] lives. A
//! change, whoever made it, reaches the matcher before it reaches the shell:
//! the next keystroke matches what the folder now says even if the shell has
//! not drawn anything yet.
//!
//! Nothing here may panic: a panic would cross the bridge as a crash in the
//! process that holds the event tap. Locks recover from poisoning instead.
//!
//! Where two locks are held at once the library is taken first and the matcher
//! second, on every thread. The keystroke path takes one at a time, which is
//! what keeps it out of the way of a save.
//!
//! There is no hand-written `unsafe` in this crate. The only `unsafe` is what
//! `uniffi::setup_scaffolding!` generates, which is why this is the one crate
//! that does not forbid it.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, MutexGuard, PoisonError, RwLock, RwLockReadGuard};

use aralo_core::compat;
use aralo_core::counters::{Count, Counters, ErrorKind};
use aralo_core::engine as matcher;
use aralo_core::snippet::{CaseMode, SnippetId, SnippetKind, TriggerMode};
use aralo_core::{
    CompatTable, Draft, ExportOptions, Format, ImportOptions, ImportReport, LibraryChange,
    LibraryListener, MacroPolicy, MatchInfo, Outcome, Query, Runtime, RuntimeOptions, Step,
};

mod ai;
mod diagnostics;

pub use ai::*;
pub use diagnostics::*;

uniffi::setup_scaffolding!();

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum BridgeError {
    #[error("{message}")]
    Library { message: String },
    #[error("{message}")]
    CompatTable { message: String },
    #[error("{message}")]
    Import { message: String },
    /// The shell's `Trash` could not take a file.
    #[error("{message}")]
    Trash { message: String },
}

/// A `Trash` written in Swift can fail in a way UniFFI has no name for, and it
/// arrives as this.
impl From<uniffi::UnexpectedUniFFICallbackError> for BridgeError {
    fn from(error: uniffi::UnexpectedUniFFICallbackError) -> Self {
        BridgeError::Trash {
            message: error.reason,
        }
    }
}

impl From<aralo_core::CoreError> for BridgeError {
    fn from(error: aralo_core::CoreError) -> Self {
        BridgeError::Library {
            message: error.to_string(),
        }
    }
}

/// A key as the shell saw it, after the keyboard layout and dead keys.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum KeyInput {
    /// A key that produced exactly one Unicode scalar. It crosses the bridge as
    /// a number so that no keystroke ever sits in a heap-allocated string. A
    /// key that produced several is not reported; the shell calls
    /// `reset(UnmappableInput)`. A key that produced none (a dead key on its
    /// own) is not reported at all.
    Char {
        scalar: u32,
    },
    Backspace,
    /// The platform's undo shortcut.
    Undo,
}

impl KeyInput {
    /// The character the key produced, when it produced one. A key the engine
    /// swallowed to make a match is what a cancelled session puts back.
    fn character(self) -> Option<char> {
        match self {
            Self::Char { scalar } => char::from_u32(scalar),
            Self::Backspace | Self::Undo => None,
        }
    }
}

/// What the shell does with the key it just reported.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum KeyAction {
    /// Let the key through.
    Pass,
    /// Swallow the key if `consume`, run the steps in order the way `profile`
    /// says, then call `expansion_done` when `undo_delete_count` is present.
    Expand {
        snippet_id: String,
        consume: bool,
        steps: Vec<PlanStep>,
        undo_delete_count: Option<u32>,
        profile: InjectionProfile,
    },
    /// Swallow the key if `consume`, then drive `session`: it has a form to
    /// put in front of the user, or context to fetch, before there is any
    /// text. Nothing has gone into the document yet, so a session the user
    /// cancels leaves what they typed where it was.
    StartSession {
        snippet_id: String,
        consume: bool,
        session: Arc<ExpansionSession>,
    },
    /// Swallow the key, take the expansion back the way `profile` says
    /// (`delete_count` Backspaces, or one undo shortcut), type `retype`.
    UndoExpansion {
        delete_count: u32,
        retype: String,
        method: InsertMethod,
        profile: InjectionProfile,
    },
}

/// What a snippet the user picked from a list does: the plan for it, or why
/// nothing goes in.
///
/// The steps are a match's steps with nothing to delete, so a snippet inserts
/// the same text however it was asked for, and the shell runs them on the same
/// injector queue.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum InsertOutcome {
    /// Run these steps in the app that was named, then report
    /// [`Engine::expansion_done`] so that the undo key takes the insertion
    /// back the way it takes an expansion back.
    Insert {
        snippet_id: String,
        steps: Vec<PlanStep>,
        undo_delete_count: Option<u32>,
        profile: InjectionProfile,
    },
    /// The snippet asks something first. Drive the session; what it ends with
    /// goes into the app that was named, exactly as `Insert` would have.
    StartSession {
        snippet_id: String,
        session: Arc<ExpansionSession>,
    },
    /// Nothing goes in, and why. The picker is the one place a user is told
    /// this: an expansion they typed simply does not happen.
    Refused { reason: InsertRefusal },
}

/// Whether a command on selected text may run in an app.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum CommandTarget {
    /// Read the selection and paste over it the way this row of the
    /// compatibility table says.
    Ready { profile: InjectionProfile },
    /// Leave the app alone, and why.
    Refused { reason: InsertRefusal },
}

/// Why a pick inserts nothing. None of them is about the snippet's own text.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum InsertRefusal {
    /// Aralo is paused, which is a pause of every insertion, not only of the
    /// ones the user did not ask for.
    Paused,
    /// The app is one Aralo stays out of (PRD P2, E10).
    ExcludedApp,
    /// The snippet is no longer in the library: deleted, or its file moved,
    /// between the list being drawn and Enter being pressed.
    SnippetGone,
}

/// How to insert, delete and undo in the app that has the keyboard; one row of
/// the compatibility table (`data/compat/apps.toml`). The shell follows it and
/// chooses nothing itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Record)]
pub struct InjectionProfile {
    pub insert: InsertChoice,
    /// The longest text `Auto` still types, in UTF-16 units.
    pub typing_limit: u32,
    /// Pause after every synthetic key.
    pub key_delay_ms: u32,
    /// How long the app gets to read the pasteboard before it is restored.
    pub paste_settle_ms: u32,
    pub undo: UndoStyle,
    pub delete: DeleteStrategy,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum InsertChoice {
    /// Type short single-line text, paste the rest.
    Auto,
    /// Always type. A line break is a Return key.
    Type,
    /// Always paste.
    Paste,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum UndoStyle {
    /// A pasted expansion is undone with one undo shortcut.
    Native,
    /// Every expansion is undone with Backspace.
    Backspace,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum DeleteStrategy {
    /// One Backspace per character.
    Backspace,
    /// Shift+Left over the characters, then one Backspace.
    Select,
}

/// One step of an expansion plan; see `docs/format/expansion-plan.md`.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum PlanStep {
    Delete { count: u32 },
    InsertText { text: String },
    InsertRich { html: String, plain: String },
    KeyPress { key: PlanKey },
    Delay { millis: u32 },
    MoveCursor { graphemes: u32, select: bool },
}

/// One expansion that cannot happen on the keystroke, because someone has to
/// be asked first: a form to fill in, the clipboard to read, or both.
///
/// The shell calls [`next`](Self::next) for the question, answers it, and
/// repeats until it gets `Expand`. Nothing reaches the document before that,
/// so [`cancel`](Self::cancel) leaves the user's text as they typed it.
///
/// While a panel is open the keys the user presses are the panel's, not the
/// document's. The shell resets the engine when it opens one, so nothing typed
/// into a form can complete an abbreviation.
#[derive(uniffi::Object)]
pub struct ExpansionSession {
    /// `None` once the session has been cancelled: a cancelled session cannot
    /// be made to insert anything.
    session: Mutex<Option<aralo_core::Session>>,
    snippet_id: String,
    /// The app the text is for, resolved when the session opened. The user may
    /// bring another app forward while the panel is up; the text still goes in
    /// the way the app it was started for wants it.
    profile: InjectionProfile,
    /// Where a cancel is counted. `None` for the editor's test field, which
    /// is not the user typing.
    counters: Option<Arc<Counters>>,
}

// Like the engine, never prints what was typed, and a session holds answers.
impl std::fmt::Debug for ExpansionSession {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ExpansionSession")
            .field("snippet_id", &self.snippet_id)
            .finish_non_exhaustive()
    }
}

/// Two handles are equal when they are the same session. What is inside one is
/// never compared: it holds what the user typed into a form.
impl PartialEq for ExpansionSession {
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(self, other)
    }
}

impl Eq for ExpansionSession {}

/// What the shell does next with a session.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum SessionAction {
    /// Put these fields in front of the user, then call `submit_form`, or
    /// `cancel` if they change their mind.
    Form { fields: Vec<FormFieldInfo> },
    /// Fetch these and call `provide_context`. The list is what the snippet
    /// asked for; nothing else is wanted, and anything else is dropped (PRD
    /// P4).
    Context { kinds: Vec<ContextNeed> },
    /// Ask a model for each of these blocks with `AiProfiles.run_block`, show
    /// the answers, and settle each block with `answer_block` or
    /// `fall_back`. The list is the blocks not yet settled.
    Ai { blocks: Vec<AiBlockInfo> },
    /// Run the steps the way `profile` says, then report `expansion_done` when
    /// `undo_delete_count` is present, exactly as for a typed expansion.
    Expand {
        snippet_id: String,
        steps: Vec<PlanStep>,
        undo_delete_count: Option<u32>,
        profile: InjectionProfile,
    },
    /// The session was cancelled. Nothing goes in.
    Done,
}

/// One field of a form, as a panel draws it.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct FormFieldInfo {
    /// What the body calls it. The same name twice is one field and one
    /// answer.
    pub name: String,
    /// What to put beside the box: the snippet's `label`, or the name.
    pub label: String,
    /// What the box starts with.
    pub default: String,
    /// Empty for a box to type in; the choices for a drop-down.
    pub options: Vec<String>,
    /// How many lines tall the box is: one for an ordinary box and for a
    /// drop-down, more for a body that asked for room to write in.
    pub lines: u32,
}

/// Something about the moment of the expansion that only the shell can fetch.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum ContextNeed {
    Clipboard,
    Selection,
    App,
    Window,
}

/// One `{{ai}}` block of a snippet, as the AI preview panel lists it.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct AiBlockInfo {
    /// What `answer_block`, `fall_back` and `run_block` know it by.
    pub index: u32,
    /// What the model is asked to write.
    pub prompt: String,
    /// What goes in when no model answers. Nothing when the body gave none,
    /// which puts in nothing.
    pub fallback: Option<String>,
}

impl From<&aralo_core::template::AiBlock> for AiBlockInfo {
    fn from(block: &aralo_core::template::AiBlock) -> Self {
        Self {
            index: u32::try_from(block.index).unwrap_or(u32::MAX),
            prompt: block.prompt.clone(),
            fallback: block.fallback.clone(),
        }
    }
}

/// What the expansion would insert, with where each block's text is: the
/// panel marks those stretches as the model's. Everything outside them is the
/// snippet's own text.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct BlockPreview {
    pub text: String,
    pub blocks: Vec<BlockSpan>,
}

/// Where one block's text sits in a `BlockPreview`, in UTF-16 code units.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Record)]
pub struct BlockSpan {
    pub block: u32,
    pub start: u32,
    pub length: u32,
}

/// What the shell fetched. A kind the snippet did not ask for is dropped by
/// the core rather than trusted to be absent.
#[derive(Debug, Clone, PartialEq, Eq, Default, uniffi::Record)]
pub struct ContextSupply {
    pub clipboard: Option<String>,
    pub selection: Option<String>,
    pub app: Option<String>,
    pub window: Option<String>,
}

impl ExpansionSession {
    fn new(
        session: aralo_core::Session,
        snippet_id: String,
        profile: InjectionProfile,
        counters: Option<Arc<Counters>>,
    ) -> Arc<Self> {
        Arc::new(Self {
            session: Mutex::new(Some(session)),
            snippet_id,
            profile,
            counters,
        })
    }

    fn held(&self) -> MutexGuard<'_, Option<aralo_core::Session>> {
        self.session.lock().unwrap_or_else(PoisonError::into_inner)
    }

    fn act(&self, step: aralo_core::SessionStep) -> SessionAction {
        match step {
            aralo_core::SessionStep::Form(form) => SessionAction::Form {
                fields: form.fields.iter().map(FormFieldInfo::from).collect(),
            },
            aralo_core::SessionStep::Context(kinds) => SessionAction::Context {
                kinds: kinds.into_iter().map(ContextNeed::from).collect(),
            },
            aralo_core::SessionStep::Ai(blocks) => SessionAction::Ai {
                blocks: blocks.iter().map(AiBlockInfo::from).collect(),
            },
            aralo_core::SessionStep::Ready(expansion) => SessionAction::Expand {
                snippet_id: self.snippet_id.clone(),
                steps: expansion
                    .plan
                    .steps
                    .into_iter()
                    .map(PlanStep::from)
                    .collect(),
                undo_delete_count: expansion.undo_delete_count,
                profile: self.profile,
            },
        }
    }
}

#[uniffi::export]
impl ExpansionSession {
    /// Which snippet is expanding.
    pub fn snippet_id(&self) -> String {
        self.snippet_id.clone()
    }

    /// The question to ask, or the plan to run. Asking twice asks the same
    /// question: a session moves on when it is answered.
    pub fn next(&self) -> SessionAction {
        match self.held().as_mut() {
            Some(session) => self.act(session.step()),
            None => SessionAction::Done,
        }
    }

    /// The form is filled in. A field left out of `answers` keeps its default,
    /// and a name the form does not have is ignored.
    pub fn submit_form(&self, answers: std::collections::HashMap<String, String>) -> SessionAction {
        let answers: aralo_core::Answers = answers.into_iter().collect();
        match self.held().as_mut() {
            Some(session) => self.act(session.submit_form(answers)),
            None => SessionAction::Done,
        }
    }

    /// What the shell fetched for the kinds the snippet asked for.
    pub fn provide_context(&self, values: ContextSupply) -> SessionAction {
        let values = aralo_core::ContextValues {
            clipboard: values.clipboard,
            selection: values.selection,
            app: values.app,
            window: values.window,
        };
        match self.held().as_mut() {
            Some(session) => self.act(session.provide_context(values)),
            None => SessionAction::Done,
        }
    }

    /// Every `{{ai}}` block there is a model to ask for, settled or not.
    pub fn ai_blocks(&self) -> Vec<AiBlockInfo> {
        match self.held().as_ref() {
            Some(session) => session.ai_blocks().iter().map(AiBlockInfo::from).collect(),
            None => Vec::new(),
        }
    }

    /// What the user accepted for a block: the model's answer, edited or as
    /// it came. It goes in as literal text and is never read for
    /// placeholders. A block can be settled again until the session ends.
    pub fn answer_block(&self, index: u32, text: String) -> SessionAction {
        match self.held().as_mut() {
            Some(session) => self.act(session.answer_block(index as usize, text)),
            None => SessionAction::Done,
        }
    }

    /// No model answered a block, or the user chose its fallback: it puts in
    /// its fallback text, and the expansion says `reason`.
    pub fn fall_back(&self, index: u32, reason: String) -> SessionAction {
        match self.held().as_mut() {
            Some(session) => self.act(session.fall_back(index as usize, reason)),
            None => SessionAction::Done,
        }
    }

    /// The expansion as it would go in with the form as it stands and the
    /// blocks' text so far: `drafts` are what the models have written, or
    /// what the user edited them to, by block. A block in neither shows its
    /// fallback. It changes nothing.
    pub fn preview_blocks(
        &self,
        answers: std::collections::HashMap<String, String>,
        drafts: std::collections::HashMap<u32, String>,
    ) -> BlockPreview {
        let answers: aralo_core::Answers = answers.into_iter().collect();
        let drafts = drafts
            .into_iter()
            .map(|(index, text)| (index as usize, text))
            .collect();
        let Some(rendered) = self
            .held()
            .as_ref()
            .map(|session| session.preview_blocks(&answers, &drafts))
        else {
            return BlockPreview {
                text: String::new(),
                blocks: Vec::new(),
            };
        };
        let text = rendered.text();
        let blocks = rendered
            .ai_spans()
            .iter()
            .map(|span| {
                let start = utf16_len(&text[..span.range.start]);
                BlockSpan {
                    block: u32::try_from(span.block).unwrap_or(u32::MAX),
                    start,
                    length: utf16_len(&text[span.range.clone()]),
                }
            })
            .collect();
        BlockPreview { text, blocks }
    }

    /// What the expansion would insert as it stands, for a panel that shows
    /// the result while the form is being filled in. Empty once the session
    /// has been cancelled.
    pub fn preview(&self) -> String {
        self.preview_with(std::collections::HashMap::new())
    }

    /// The same, for a form that is being typed into: `answers` are the boxes
    /// as they stand, over what the session already has. It changes nothing,
    /// so a panel can call it on every keystroke.
    pub fn preview_with(&self, answers: std::collections::HashMap<String, String>) -> String {
        let answers: aralo_core::Answers = answers.into_iter().collect();
        match self.held().as_ref() {
            Some(session) => session.preview_with(&answers),
            None => String::new(),
        }
    }

    /// The user changed their mind. Run these steps — usually none, or the one
    /// character the engine swallowed to open the session — and forget the
    /// session.
    pub fn cancel(&self) -> Vec<PlanStep> {
        match self.held().take() {
            Some(session) => {
                if let Some(counters) = &self.counters {
                    counters.add(Count::SessionCancelled);
                }
                session
                    .cancel()
                    .steps
                    .into_iter()
                    .map(PlanStep::from)
                    .collect()
            }
            None => Vec::new(),
        }
    }
}

/// The editor's test field: a text field in memory that expands one draft.
///
/// The shell forwards the keys typed into its text view and draws what comes
/// back; the field here is the one that counts. A draft that asks something
/// hands back a session, which the shell drives with the same form panel as a
/// real expansion, then gives the plan to [`finish`](Self::finish).
#[derive(uniffi::Object)]
pub struct DraftTrial {
    trial: Mutex<aralo_core::Trial>,
    shared: Arc<Shared>,
}

// Never prints what was typed.
impl std::fmt::Debug for DraftTrial {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("DraftTrial").finish_non_exhaustive()
    }
}

/// What a key typed into the test field did.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum TrialAction {
    /// Nothing matched; the key went into the field.
    Typed,
    /// The draft expanded, or Backspace took an expansion back.
    Expanded,
    /// The draft asks something first. Drive the session, then call
    /// `finish` with its plan or `cancel` with the session.
    Session { session: Arc<ExpansionSession> },
}

/// The test field as a text view draws it. Offsets are UTF-16 code units.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct TrialField {
    pub text: String,
    /// Where the caret is, or where the selection starts.
    pub caret: u32,
    /// How much is selected after `caret`; zero when nothing is.
    pub selected: u32,
}

impl DraftTrial {
    fn held(&self) -> MutexGuard<'_, aralo_core::Trial> {
        self.trial.lock().unwrap_or_else(PoisonError::into_inner)
    }
}

#[uniffi::export]
impl DraftTrial {
    /// One key, typed at the caret.
    pub fn key(&self, key: KeyInput) -> TrialAction {
        let event = match key {
            KeyInput::Char { scalar } => match char::from_u32(scalar) {
                Some(c) => matcher::KeyEvent::Char(c),
                None => return TrialAction::Typed,
            },
            KeyInput::Backspace => matcher::KeyEvent::Backspace,
            KeyInput::Undo => matcher::KeyEvent::Undo,
        };
        let mut trial = self.held();
        let id = trial.snippet_id().to_string();
        let done = self.shared.runtime().read(|core| trial.key(core, event));
        match done {
            aralo_core::TrialKey::Typed => TrialAction::Typed,
            aralo_core::TrialKey::Expanded => TrialAction::Expanded,
            aralo_core::TrialKey::Session(session) => TrialAction::Session {
                session: ExpansionSession::new(
                    *session,
                    id,
                    self.shared.compat().profile_for("").into(),
                    None,
                ),
            },
        }
    }

    /// Runs the plan a session came to, from `SessionAction::Expand`.
    pub fn finish(&self, steps: Vec<PlanStep>, undo_delete_count: Option<u32>) {
        let plan = aralo_core::ExpansionPlan {
            steps: steps.into_iter().map(Step::from).collect(),
        };
        self.held().finish(&aralo_core::Expansion {
            plan,
            undo_delete_count,
            template_diagnostics: Vec::new(),
        });
    }

    /// The user closed the panel: the key that opened it goes back.
    pub fn cancel(&self, session: Arc<ExpansionSession>) {
        let plan = aralo_core::ExpansionPlan {
            steps: session.cancel().into_iter().map(Step::from).collect(),
        };
        self.held().put_back(&plan);
    }

    /// The user clicked or pressed an arrow key: the caret is at `caret`, in
    /// UTF-16 code units, and what was typed before no longer leads up to it.
    pub fn move_caret(&self, caret: u32) {
        let mut trial = self.held();
        let at = byte_offset(trial.text(), caret);
        trial.move_caret(at);
    }

    pub fn clear(&self) {
        self.held().clear();
    }

    /// The field as it stands, for the text view to draw.
    pub fn field(&self) -> TrialField {
        let trial = self.held();
        let text = trial.text();
        let (start, end) = match trial.selection() {
            Some(range) => (range.start, range.end),
            None => (trial.caret(), trial.caret()),
        };
        let caret = utf16_len(&text[..start]);
        TrialField {
            text: text.to_owned(),
            caret,
            selected: utf16_len(&text[start..end]),
        }
    }

    /// How many of the draft's abbreviations can be typed into the field. Zero
    /// means nothing typed there will expand, which the editor says.
    pub fn abbreviations(&self) -> u32 {
        u32::try_from(self.held().abbreviations()).unwrap_or(u32::MAX)
    }
}

fn utf16_len(text: &str) -> u32 {
    u32::try_from(text.encode_utf16().count()).unwrap_or(u32::MAX)
}

/// The byte offset of the character boundary at or before `units` UTF-16 code
/// units into `text`.
fn byte_offset(text: &str, units: u32) -> usize {
    let mut seen = 0u32;
    for (at, c) in text.char_indices() {
        let width = u32::try_from(c.len_utf16()).unwrap_or(2);
        if seen + width > units {
            return at;
        }
        seen += width;
    }
    text.len()
}

impl From<&aralo_core::FormField> for FormFieldInfo {
    fn from(field: &aralo_core::FormField) -> Self {
        Self {
            name: field.name.clone(),
            label: field.label.clone(),
            default: field.default().to_owned(),
            options: match &field.kind {
                aralo_core::FieldKind::Choice { options } => options.clone(),
                aralo_core::FieldKind::Line | aralo_core::FieldKind::Area { .. } => Vec::new(),
            },
            lines: match &field.kind {
                aralo_core::FieldKind::Area { lines } => *lines,
                aralo_core::FieldKind::Line | aralo_core::FieldKind::Choice { .. } => 1,
            },
        }
    }
}

impl From<aralo_core::ContextKind> for ContextNeed {
    fn from(kind: aralo_core::ContextKind) -> Self {
        match kind {
            aralo_core::ContextKind::Clipboard => Self::Clipboard,
            aralo_core::ContextKind::Selection => Self::Selection,
            aralo_core::ContextKind::App => Self::App,
            aralo_core::ContextKind::Window => Self::Window,
        }
    }
}

/// One app the compatibility table names, with its row resolved.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct CompatApp {
    pub name: String,
    pub bundle_id: String,
    pub profile: InjectionProfile,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum PlanKey {
    Return,
    Tab,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum InsertMethod {
    Typed,
    Pasted,
}

/// Why the shell is clearing the buffer. Every reason zeroes it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum ResetReason {
    MouseDown,
    Navigation,
    Shortcut,
    AppSwitch,
    FocusChange,
    SecureInput,
    InputMethod,
    UnmappableInput,
    Manual,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct SnippetSummary {
    pub id: String,
    pub label: String,
    pub abbreviations: Vec<String>,
    /// Folder names from the library root down to the snippet's group.
    pub group: Vec<String>,
    /// Path from the library root.
    pub path: String,
    pub enabled: bool,
    /// The start of the body, for a list row.
    pub preview: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum DiagnosticLevel {
    Error,
    Warning,
    Note,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct LibraryDiagnostic {
    /// Path from the library root.
    pub path: String,
    pub level: DiagnosticLevel,
    pub message: String,
}

/// The library both objects share, running: watched, indexed, and read under a
/// lock the keystroke path only ever holds for the length of one lookup.
struct Shared {
    /// Replaced whole when the library moves (plan 5.2). A call takes its own
    /// handle and lets go of the lock at once, so a move waits for no one and
    /// no one waits for a move.
    runtime: RwLock<Arc<Runtime>>,
    compat: RwLock<CompatTable>,
    /// The local counters (plan 5.7), kept beside the index.
    counters: Arc<Counters>,
    /// What a runtime is started with, kept to start the next one.
    start: Start,
    /// The model `use_model` named, for the runtime of a moved library.
    model: Mutex<Option<(PathBuf, Arc<AiProfiles>)>>,
}

impl Shared {
    fn runtime(&self) -> Arc<Runtime> {
        Arc::clone(&self.runtime.read().unwrap_or_else(PoisonError::into_inner))
    }

    fn compat(&self) -> RwLockReadGuard<'_, CompatTable> {
        self.compat.read().unwrap_or_else(PoisonError::into_inner)
    }

    /// Runs the library at `root` in place of the one running now: the old
    /// runtime's watch and indexer stop, the model is taken up again, and the
    /// matcher and the shell hear `Reloaded` from the new one.
    fn switch_to(&self, root: &Path) -> Result<(), BridgeError> {
        let runtime = Arc::new(self.start.runtime(aralo_core::Core::open(root)?)?);
        if runtime.index_error().is_some() {
            self.counters.error(ErrorKind::IndexUnavailable);
        }
        if let Some((folder, ai)) = &*self.model.lock().unwrap_or_else(PoisonError::into_inner) {
            runtime.use_model(folder.clone(), ai.settings());
        }
        let old = std::mem::replace(
            &mut *self.runtime.write().unwrap_or_else(PoisonError::into_inner),
            Arc::clone(&runtime),
        );
        // Stopped here, outside the lock, unless a call still holds it; then
        // it stops when that call is done.
        drop(old);
        runtime.reload()?;
        Ok(())
    }
}

/// How the bridge starts a runtime on a library.
struct Start {
    cache: Option<PathBuf>,
    trash: Option<Arc<dyn Trash>>,
    listener: Arc<Events>,
}

impl Start {
    fn runtime(&self, library: aralo_core::Core) -> Result<Runtime, BridgeError> {
        let root = library.root().to_path_buf();
        let options = RuntimeOptions {
            index: self
                .cache
                .as_deref()
                .map(|cache| aralo_core::state::index_in(cache, &root)),
            // A shell that has no Trash to offer gets the copies set aside
            // beside the index, in the folder it named.
            discard: match &self.trash {
                Some(trash) => {
                    Some(Arc::new(ShellTrash(Arc::clone(trash))) as Arc<dyn aralo_core::Discard>)
                }
                None => self.cache.as_deref().map(|cache| {
                    Arc::new(aralo_core::SetAside::new(aralo_core::state::set_aside_in(
                        cache, &root,
                    ))) as Arc<dyn aralo_core::Discard>
                }),
            },
            ..RuntimeOptions::default()
        };
        Ok(Runtime::with_core(
            library,
            options,
            Arc::clone(&self.listener) as Arc<dyn LibraryListener>,
        )?)
    }
}

/// What the runtime tells the bridge, and what the bridge does about it: the
/// matcher gets the new snapshot, then the shell is told.
struct Events {
    matcher: Arc<Mutex<matcher::Engine>>,
    shell: Option<Arc<dyn CoreEvents>>,
    counters: Arc<Counters>,
}

impl LibraryListener for Events {
    fn changed(&self, change: LibraryChange, library: &aralo_core::Core) {
        match &change {
            LibraryChange::Outside { .. } => self.counters.add(Count::OutsideChanges),
            LibraryChange::Failed { .. } => self.counters.error(ErrorKind::LibraryReadFailed),
            LibraryChange::Merged { copies } => self
                .counters
                .add_n(Count::ConflictsMerged, copies.len() as u64),
            _ => {}
        }
        // The snapshot first, and whether or not anyone is listening: a shell
        // that shows nothing still expands what the folder says.
        if !matches!(change, LibraryChange::Indexed { .. }) {
            self.matcher
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .set_snapshot(library.snapshot());
        }
        if let Some(shell) = &self.shell {
            shell.library_changed(change.into());
        }
    }
}

/// The app that receives keys, and its row of the compatibility table. Looked
/// up when the app changes, so a match only has to copy it.
struct FrontApp {
    bundle_id: String,
    profile: compat::InjectionProfile,
}

/// The keystroke path.
#[derive(uniffi::Object)]
pub struct Engine {
    /// Shared with [`Events`], which swaps the snapshot in when the library
    /// changes. The tap thread and the watch thread both take this lock; both
    /// hold it for one call.
    matcher: Arc<Mutex<matcher::Engine>>,
    front_app: Mutex<FrontApp>,
    shared: Arc<Shared>,
}

impl std::fmt::Debug for Engine {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Engine").finish_non_exhaustive()
    }
}

impl Engine {
    fn matcher(&self) -> MutexGuard<'_, matcher::Engine> {
        self.matcher.lock().unwrap_or_else(PoisonError::into_inner)
    }

    fn front_app(&self) -> MutexGuard<'_, FrontApp> {
        self.front_app
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
    }

    /// Not taken on the way in: only a match or an undo needs it.
    fn profile(&self) -> InjectionProfile {
        self.front_app().profile.into()
    }

    /// Looks the front app up again, after the table changed.
    fn refresh_profile(&self) {
        let mut front_app = self.front_app();
        front_app.profile = self.shared.compat().profile_for(&front_app.bundle_id);
    }
}

#[uniffi::export]
impl Engine {
    pub fn on_key(&self, key: KeyInput) -> KeyAction {
        let event = match key {
            KeyInput::Char { scalar } => match char::from_u32(scalar) {
                Some(c) => matcher::KeyEvent::Char(c),
                None => {
                    self.matcher().reset(matcher::ResetReason::UnmappableInput);
                    self.shared.counters.add(Count::ResetUnmappableInput);
                    return KeyAction::Pass;
                }
            },
            KeyInput::Backspace => matcher::KeyEvent::Backspace,
            KeyInput::Undo => matcher::KeyEvent::Undo,
        };
        // The engine lock is released before the plan is built.
        let verdict = self.matcher().on_key(event);
        match verdict {
            matcher::KeyVerdict::Pass => KeyAction::Pass,
            matcher::KeyVerdict::Match {
                snippet_id,
                delete_count,
                consume,
                case,
                trailing,
            } => {
                let started = std::time::Instant::now();
                let expand = self.shared.runtime().read(|core| {
                    core.expand(MatchInfo {
                        snippet_id,
                        delete_count,
                        case,
                        trailing,
                        swallowed: consume.then_some(key).and_then(KeyInput::character),
                    })
                });
                let id = SnippetId::from_u128(snippet_id.0).to_string();
                self.count_match(&expand, started);
                match expand {
                    Some(aralo_core::Expand::Ready(expansion)) => KeyAction::Expand {
                        snippet_id: id,
                        consume,
                        steps: expansion
                            .plan
                            .steps
                            .into_iter()
                            .map(PlanStep::from)
                            .collect(),
                        undo_delete_count: expansion.undo_delete_count,
                        profile: self.profile(),
                    },
                    Some(aralo_core::Expand::Session(session)) => KeyAction::StartSession {
                        session: ExpansionSession::new(
                            *session,
                            id.clone(),
                            self.profile(),
                            Some(Arc::clone(&self.shared.counters)),
                        ),
                        snippet_id: id,
                        consume,
                    },
                    // The snippet went away between the snapshot and now.
                    None => KeyAction::Pass,
                }
            }
            matcher::KeyVerdict::UndoLast {
                delete_count,
                retype,
                method,
            } => {
                self.shared.counters.add(Count::Undone);
                self.shared.counters.undone_in(&self.front_app().bundle_id);
                KeyAction::UndoExpansion {
                    delete_count,
                    retype,
                    method: match method {
                        matcher::InsertMethod::Typed => InsertMethod::Typed,
                        matcher::InsertMethod::Pasted => InsertMethod::Pasted,
                    },
                    profile: self.profile(),
                }
            }
        }
    }

    /// The plan for a snippet the user picked from a list, and the profile of
    /// the app it is going into.
    ///
    /// `into_app` is named rather than read from [`Engine::set_front_app`]
    /// because a picker holds the keyboard while the user chooses: the app in
    /// front is Aralo's own window, and the text is for the app behind it. The
    /// plan follows that app's row of the compatibility table, so a pick goes
    /// in the way typing the abbreviation there would.
    ///
    /// The buffer is cleared, so what was typed before the picker opened cannot
    /// complete an abbreviation across the inserted text. The named app becomes
    /// the front app, so the shell may call this the moment it has brought that
    /// app forward, without waiting for the system to say so.
    pub fn insert(&self, snippet_id: String, into_app: String) -> InsertOutcome {
        let refused = |reason| {
            self.shared.counters.add(match reason {
                InsertRefusal::Paused => Count::RefusedPaused,
                InsertRefusal::ExcludedApp => Count::RefusedExcludedApp,
                InsertRefusal::SnippetGone => Count::RefusedSnippetGone,
            });
            InsertOutcome::Refused { reason }
        };
        let Ok(id) = snippet_id.parse::<SnippetId>() else {
            return refused(InsertRefusal::SnippetGone);
        };
        // The library's lock first and the matcher's second, as everywhere
        // else; neither is held while the other is.
        let Some(expand) = self.shared.runtime().read(|core| core.insert(id)) else {
            return refused(InsertRefusal::SnippetGone);
        };
        let recorded = self
            .matcher()
            .chosen(matcher::SnippetId(id.as_u128()), &into_app);
        if let Err(reason) = recorded {
            return refused(match reason {
                matcher::InsertRefusal::Paused => InsertRefusal::Paused,
                matcher::InsertRefusal::ExcludedApp => InsertRefusal::ExcludedApp,
            });
        }
        // The app the text is for is the app that has the keyboard as far as
        // the core is concerned, so that an undo of this insertion follows that
        // app's row of the table rather than Aralo's own window's.
        let profile = self.shared.compat().profile_for(&into_app);
        self.shared.counters.add(Count::Picked);
        *self.front_app() = FrontApp {
            bundle_id: into_app,
            profile,
        };
        match expand {
            aralo_core::Expand::Ready(expansion) => InsertOutcome::Insert {
                snippet_id: id.to_string(),
                steps: expansion
                    .plan
                    .steps
                    .into_iter()
                    .map(PlanStep::from)
                    .collect(),
                undo_delete_count: expansion.undo_delete_count,
                profile: profile.into(),
            },
            aralo_core::Expand::Session(session) => InsertOutcome::StartSession {
                session: ExpansionSession::new(
                    *session,
                    id.to_string(),
                    profile.into(),
                    Some(Arc::clone(&self.shared.counters)),
                ),
                snippet_id: id.to_string(),
            },
        }
    }

    /// Arms undo for the expansion that `on_key` just returned, and counts it
    /// towards the recents list. The count is queued, not written here: this is
    /// called the moment the text lands, and that thread waits for nothing.
    pub fn expansion_done(&self, snippet_id: String, delete_count: u32, method: InsertMethod) {
        let Ok(id) = snippet_id.parse::<SnippetId>() else {
            return;
        };
        self.shared.runtime().record_expansion(id);
        self.shared.counters.add(match method {
            InsertMethod::Typed => Count::InsertedTyped,
            InsertMethod::Pasted => Count::InsertedPasted,
        });
        self.shared
            .counters
            .expanded_in(&self.front_app().bundle_id);
        self.matcher().expansion_done(matcher::ExpansionRecord {
            snippet_id: matcher::SnippetId(id.as_u128()),
            delete_count,
            method: match method {
                InsertMethod::Typed => matcher::InsertMethod::Typed,
                InsertMethod::Pasted => matcher::InsertMethod::Pasted,
            },
        });
    }

    pub fn reset(&self, reason: ResetReason) {
        self.shared.counters.add(match reason {
            ResetReason::MouseDown => Count::ResetMouseDown,
            ResetReason::Navigation => Count::ResetNavigation,
            ResetReason::Shortcut => Count::ResetShortcut,
            ResetReason::AppSwitch => Count::ResetAppSwitch,
            ResetReason::FocusChange => Count::ResetFocusChange,
            ResetReason::SecureInput => Count::ResetSecureInput,
            ResetReason::InputMethod => Count::ResetInputMethod,
            ResetReason::UnmappableInput => Count::ResetUnmappableInput,
            ResetReason::Manual => Count::ResetManual,
        });
        self.matcher().reset(match reason {
            ResetReason::MouseDown => matcher::ResetReason::MouseDown,
            ResetReason::Navigation => matcher::ResetReason::Navigation,
            ResetReason::Shortcut => matcher::ResetReason::Shortcut,
            ResetReason::AppSwitch => matcher::ResetReason::AppSwitch,
            ResetReason::FocusChange => matcher::ResetReason::FocusChange,
            ResetReason::SecureInput => matcher::ResetReason::SecureInput,
            ResetReason::InputMethod => matcher::ResetReason::InputMethod,
            ResetReason::UnmappableInput => matcher::ResetReason::UnmappableInput,
            ResetReason::Manual => matcher::ResetReason::Manual,
        });
    }

    /// The bundle ID of the app that now receives keys.
    pub fn set_front_app(&self, bundle_id: String) {
        self.matcher().set_front_app(&bundle_id);
        let profile = self.shared.compat().profile_for(&bundle_id);
        *self.front_app() = FrontApp { bundle_id, profile };
    }

    /// How text goes into the app that has the keyboard now.
    pub fn injection_profile(&self) -> InjectionProfile {
        self.profile()
    }

    /// Whether a command may read the selection in `app` and replace it: not
    /// while paused, and never in an excluded app. When it may, the buffer
    /// and the undo record are cleared, since what is around the caret is
    /// about to change, and the answer carries `app`'s row of the table.
    pub fn command_target(&self, app: String) -> CommandTarget {
        if let Err(reason) = self.matcher().command_in(&app) {
            return CommandTarget::Refused {
                reason: match reason {
                    matcher::InsertRefusal::Paused => InsertRefusal::Paused,
                    matcher::InsertRefusal::ExcludedApp => InsertRefusal::ExcludedApp,
                },
            };
        }
        CommandTarget::Ready {
            profile: self.shared.compat().profile_for(&app).into(),
        }
    }

    pub fn set_paused(&self, paused: bool) {
        self.matcher().set_paused(paused);
    }

    pub fn is_paused(&self) -> bool {
        self.matcher().is_paused()
    }

    /// Apps the user excluded. The built-in presets (password managers) stay
    /// excluded as well: the engine's own call replaces the whole list, and a
    /// shell that forgot to pass the presets along would silently drop them.
    pub fn set_excluded_apps(&self, mut bundle_ids: Vec<String>) {
        bundle_ids.extend(excluded_app_presets());
        self.matcher().set_excluded_apps(bundle_ids);
    }

    /// True when the buffer holds nothing. For the privacy self-test.
    pub fn holds_no_keystrokes(&self) -> bool {
        self.matcher().holds_no_keystrokes()
    }
}

/// The open library.
#[derive(uniffi::Object)]
pub struct Core {
    shared: Arc<Shared>,
    engine: Arc<Engine>,
}

impl std::fmt::Debug for Core {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Core").finish_non_exhaustive()
    }
}

#[uniffi::export]
impl Core {
    /// Opens the library folder, creating it (with the starter snippets) when
    /// it does not exist yet, and starts watching and indexing it.
    ///
    /// `cache` is the folder Aralo may keep rebuildable files in — the search
    /// index, and nothing the user would miss. The shell passes the one its
    /// platform gives it, because a sandboxed app's is not where an unsandboxed
    /// one's is; nothing means work it out, which is what the command line
    /// does. A cache that will not open costs recents and usage counts and
    /// nothing else: `index_problem` then says why.
    ///
    /// `events` is how the shell hears about changes it did not make. A shell
    /// that passes none still expands: the matcher is brought up to date
    /// either way.
    ///
    /// `trash` is where a conflict copy goes once it has been merged or
    /// resolved. Without one it is set aside in the cache folder, where the
    /// user will not find it.
    #[uniffi::constructor]
    pub fn open_library(
        path: String,
        cache: Option<String>,
        events: Option<Arc<dyn CoreEvents>>,
        trash: Option<Arc<dyn Trash>>,
    ) -> Result<Arc<Self>, BridgeError> {
        let root = PathBuf::from(path);
        let library = aralo_core::Core::open(&root)?;
        let matcher = Arc::new(Mutex::new(library.engine()));
        let cache = cache.map(PathBuf::from);
        let counters = Counters::shared(cache.as_deref());
        let listener = Arc::new(Events {
            matcher: Arc::clone(&matcher),
            shell: events,
            counters: Arc::clone(&counters),
        });
        let start = Start {
            cache,
            trash,
            listener,
        };
        let runtime = start.runtime(library)?;
        if runtime.index_error().is_some() {
            counters.error(ErrorKind::IndexUnavailable);
        }
        let compat = CompatTable::bundled();
        let front_app = FrontApp {
            bundle_id: String::new(),
            profile: compat.defaults(),
        };
        let shared = Arc::new(Shared {
            runtime: RwLock::new(Arc::new(runtime)),
            compat: RwLock::new(compat),
            counters,
            start,
            model: Mutex::new(None),
        });
        let engine = Arc::new(Engine {
            matcher,
            front_app: Mutex::new(front_app),
            shared: Arc::clone(&shared),
        });
        Ok(Arc::new(Self { shared, engine }))
    }

    /// The engine for this library. There is one; every call returns it.
    pub fn engine(&self) -> Arc<Engine> {
        Arc::clone(&self.engine)
    }

    /// Reads the folder again. The engine gets the new snapshot and the shell
    /// hears `Reloaded`; on failure the library that was loaded stays in use.
    ///
    /// Nothing has to call this to see an outside change: the watch does. It is
    /// for a folder that arrived while Aralo was not looking, and for a user
    /// who would rather be sure.
    pub fn reload(&self) -> Result<(), BridgeError> {
        Ok(self.shared.runtime().reload()?)
    }

    /// Replaces the built-in compatibility table with the file at `path`, for
    /// trying an app's settings without rebuilding the core. A file that does
    /// not parse changes nothing.
    pub fn load_compat_table(&self, path: String) -> Result<(), BridgeError> {
        let table = read_compat_table(&path).inspect_err(|_| {
            self.shared.counters.error(ErrorKind::CompatTableRejected);
        })?;
        *self
            .shared
            .compat
            .write()
            .unwrap_or_else(PoisonError::into_inner) = table;
        self.engine.refresh_profile();
        Ok(())
    }

    pub fn library_path(&self) -> String {
        self.shared.runtime().root().to_string_lossy().into_owned()
    }

    /// Moves the library to `to`, an empty folder or one that does not exist
    /// yet, and runs it from there (plan 5.2).
    ///
    /// Every file is copied and read back, the copy must load as the same
    /// library, and only then is it put in place and the old folder's watch
    /// stopped. The counts and recents come along. The old folder is left as
    /// it was: the shell moves it to the Trash, and only when
    /// `changed_after_copy` is empty. On failure nothing has changed and the
    /// library runs where it was.
    pub fn move_library(&self, to: String) -> Result<LibraryMove, BridgeError> {
        let runtime = self.shared.runtime();
        // What was counted so far is in the index before it is copied.
        runtime.flush();
        let moved = aralo_core::move_library(
            &runtime.root(),
            Path::new(&to),
            self.shared.start.cache.as_deref(),
        )
        .map_err(|error| BridgeError::Library {
            message: error.to_string(),
        })?;
        drop(runtime);
        self.shared.switch_to(&moved.to)?;
        Ok(LibraryMove {
            from: moved.from.to_string_lossy().into_owned(),
            to: moved.to.to_string_lossy().into_owned(),
            files: moved.files as u32,
            snippets: moved.snippets as u32,
            changed_after_copy: moved
                .changed_since()
                .iter()
                .map(|path| aralo_core::slashed(path))
                .collect(),
            index_problem: moved.index_problem,
        })
    }

    /// Runs the library that is already at `path`, another Mac's synced
    /// there, say, in place of this one. Nothing is copied, and the library
    /// that was running is left where it is.
    pub fn switch_library(&self, path: String) -> Result<(), BridgeError> {
        let root = PathBuf::from(path);
        if !matches!(
            aralo_core::relocate::inspect(&root).contents,
            aralo_core::Contents::Library { .. }
        ) {
            return Err(BridgeError::Library {
                message: format!("{} is not an Aralo library", root.display()),
            });
        }
        self.shared.switch_to(&root)
    }

    /// The commands to run on selected text: the built-in ones, then the
    /// library's `type: command` snippets.
    pub fn commands(&self) -> Vec<AiCommand> {
        self.shared
            .runtime()
            .read(|core| core.commands().iter().map(AiCommand::from).collect())
    }

    pub fn snippets(&self) -> Vec<SnippetSummary> {
        self.shared
            .runtime()
            .read(|core| core.snippets().iter().map(summarise).collect())
    }

    pub fn diagnostics(&self) -> Vec<LibraryDiagnostic> {
        self.shared.runtime().read(|core| {
            core.diagnostics()
                .map(|diagnostic| {
                    let (level, message) = describe(&diagnostic.issue);
                    LibraryDiagnostic {
                        path: diagnostic.path.to_string_lossy().into_owned(),
                        level,
                        message,
                    }
                })
                .collect()
        })
    }
}

/// Sync conflicts: the copies a sync client left that did not merge on their
/// own, and the user's decision about each.
#[uniffi::export]
impl Core {
    /// The conflict copies waiting for the user, in path order.
    pub fn conflicts(&self) -> Vec<ConflictSummary> {
        self.shared.runtime().read(|core| {
            let mut conflicts: Vec<_> = core
                .conflicts()
                .iter()
                .map(|conflict| ConflictSummary {
                    copy: conflict.copy.to_string_lossy().into_owned(),
                    original: conflict.original.to_string_lossy().into_owned(),
                    snippet_id: conflict.id.to_string(),
                })
                .collect();
            conflicts.sort_by(|a, b| a.copy.cmp(&b.copy));
            conflicts
        })
    }

    /// Both sides of the conflict copy at `copy`, a path relative to the
    /// library root, for the resolver to show.
    pub fn conflict(&self, copy: String) -> Result<ConflictDetail, BridgeError> {
        let sides = self.shared.runtime().conflict(&PathBuf::from(copy))?;
        Ok(ConflictDetail {
            copy: sides.conflict.copy.to_string_lossy().into_owned(),
            original: sides.conflict.original.to_string_lossy().into_owned(),
            snippet_id: sides.conflict.id.to_string(),
            original_text: sides.original,
            copy_text: sides.copy,
            base_text: sides.base,
            clashing_keys: sides.clashes.keys,
            body_clashes: sides.clashes.body,
            copy_problem: sides.copy_problem,
        })
    }

    /// Settles the conflict copy at `copy` and puts the copy in the trash.
    /// The shell hears `Edited`.
    pub fn resolve_conflict(
        &self,
        copy: String,
        choice: ConflictChoice,
    ) -> Result<(), BridgeError> {
        let resolution = match choice {
            ConflictChoice::KeepOriginal => aralo_core::Resolution::KeepOriginal,
            ConflictChoice::KeepCopy => aralo_core::Resolution::KeepCopy,
            ConflictChoice::Write { text } => aralo_core::Resolution::Write(text),
        };
        Ok(self
            .shared
            .runtime()
            .resolve_conflict(&PathBuf::from(copy), resolution)?)
    }
}

/// What a save from the editor came to.
#[derive(Debug, Clone, PartialEq, uniffi::Enum)]
pub enum SaveOutcome {
    /// The draft is in the file, with any change made on disk since merged
    /// in. `id` differs from the one saved only for a hand-written file that
    /// carried none until now.
    Written { id: String },
    /// The file changed on disk where the draft did. Nothing was written.
    Clashed { clash: SaveClash },
}

/// A draft and the file under it that both changed one thing, differently.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct SaveClash {
    /// The file as it is on disk now.
    pub disk_text: String,
    /// Its fields as the editor would open them; nil when it no longer reads
    /// as a snippet.
    pub disk: Option<SnippetDraft>,
    /// The file as the draft would have written it.
    pub mine_text: String,
    /// The file as it stood when the editor opened.
    pub base_text: String,
    /// Front-matter keys both changed, differently.
    pub clashing_keys: Vec<String>,
    /// Both changed the same lines of the body.
    pub body_clashes: bool,
}

/// A conflict copy waiting for the user.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct ConflictSummary {
    /// The copy's path, relative to the library root.
    pub copy: String,
    /// The original's path, relative to the library root.
    pub original: String,
    pub snippet_id: String,
}

/// Everything a resolver shows about one conflict copy.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct ConflictDetail {
    pub copy: String,
    pub original: String,
    pub snippet_id: String,
    /// The two files, as they are on disk.
    pub original_text: String,
    pub copy_text: String,
    /// The version both were edited from, when this machine has it.
    pub base_text: Option<String>,
    /// Front-matter keys the two sides changed differently.
    pub clashing_keys: Vec<String>,
    /// Both sides changed the same lines of the body.
    pub body_clashes: bool,
    /// Why the copy is not a snippet file, when it is not one. Keeping the
    /// original is then the only choice that works as it is.
    pub copy_problem: Option<String>,
}

/// What the user decided about a conflict copy.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum ConflictChoice {
    /// The original stays as it is.
    KeepOriginal,
    /// The copy's version goes into the original's file.
    KeepCopy,
    /// This text, a whole snippet file, goes into the original's file.
    Write { text: String },
}

/// Where the platform keeps files a user may want back. The Mac shell's puts
/// them in the Trash.
///
/// Called with the library locked, on whichever thread read the folder: move
/// the file and return.
#[uniffi::export(with_foreign)]
pub trait Trash: Send + Sync {
    /// Moves the file at the absolute path `path` out of the library.
    fn discard(&self, path: String) -> Result<(), BridgeError>;
}

/// The shell's `Trash`, as the core's `Discard`.
struct ShellTrash(Arc<dyn Trash>);

impl std::fmt::Debug for ShellTrash {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("ShellTrash")
    }
}

impl aralo_core::Discard for ShellTrash {
    fn discard(&self, path: &std::path::Path) -> std::io::Result<()> {
        self.0
            .discard(path.to_string_lossy().into_owned())
            .map_err(std::io::Error::other)
    }
}

/// The editor: everything that changes the folder, and everything the editor
/// needs to show before it does.
///
/// Every call here writes files and reads the folder again, so what comes back
/// from `snippets()` next is what a text editor would show. A `Core` with an
/// `events` listener hears `Edited` for each one.
#[uniffi::export]
impl Core {
    /// Every group in the library, root first, then in folder order.
    pub fn groups(&self) -> Vec<GroupSummary> {
        self.shared.runtime().read(|core| {
            core.library()
                .groups()
                .iter()
                .map(|group| GroupSummary {
                    path: group.path.clone(),
                    name: group.name.clone(),
                    colour: group.colour.clone(),
                    icon: group.icon.clone(),
                    enabled: group.enabled,
                    snippets: group.snippets as u32,
                })
                .collect()
        })
    }

    /// One snippet, with everything the editor puts on screen. `None` when
    /// there is no snippet with that ID.
    pub fn snippet(&self, id: String) -> Option<SnippetDetail> {
        let id = id.parse::<SnippetId>().ok()?;
        self.shared.runtime().read(|core| {
            let snippet = core.library().snippet(id)?;
            Some(SnippetDetail {
                id: snippet.id.to_string(),
                path: snippet.path.to_string_lossy().into_owned(),
                group: snippet.group.clone(),
                draft: SnippetDraft::from(&Draft::of(snippet)),
                resolved: ResolvedSettings {
                    trigger: match snippet.settings.trigger {
                        matcher::Trigger::Immediate => Trigger::Immediate,
                        matcher::Trigger::Delimiter => Trigger::Delimiter,
                    },
                    case: match snippet.settings.case {
                        matcher::CaseMode::Exact => CaseStyle::Exact,
                        matcher::CaseMode::Ignore => CaseStyle::Ignore,
                        matcher::CaseMode::Adaptive => CaseStyle::Adaptive,
                    },
                    whole_word: snippet.settings.whole_word,
                    keep_delimiter: snippet.settings.keep_delimiter,
                    enabled: snippet.settings.enabled,
                },
                preview: core.preview(id).unwrap_or_default(),
            })
        })
    }

    /// Writes a new snippet into `group` and returns its ID. An empty group is
    /// the library root.
    pub fn create_snippet(
        &self,
        group: Vec<String>,
        draft: SnippetDraft,
    ) -> Result<String, BridgeError> {
        let draft = Draft::from(&draft);
        let id = self
            .shared
            .runtime()
            .edit(|core| core.create_snippet(&group, &draft))?;
        Ok(id.to_string())
    }

    /// Writes `draft` over the snippet `id`, in the file it is already in, and
    /// returns its ID afterwards. That differs from `id` only for a
    /// hand-written file that carried none until now.
    pub fn save_snippet(&self, id: String, draft: SnippetDraft) -> Result<String, BridgeError> {
        let id = snippet_id(&id)?;
        let draft = Draft::from(&draft);
        let saved = self
            .shared
            .runtime()
            .edit(|core| core.save_snippet(id, &draft))?;
        Ok(saved.to_string())
    }

    /// Writes `draft` over the snippet `id`, keeping whatever changed in its
    /// file since the editor opened it on `opened` (plan 5.1). A change on
    /// disk that touched what the draft touched writes nothing and comes back
    /// as `Clashed`; saving again with `opened` set to the clash's `disk`
    /// keeps the draft.
    pub fn save_snippet_since(
        &self,
        id: String,
        opened: SnippetDraft,
        draft: SnippetDraft,
    ) -> Result<SaveOutcome, BridgeError> {
        let id = snippet_id(&id)?;
        let opened = Draft::from(&opened);
        let draft = Draft::from(&draft);
        let saved = self
            .shared
            .runtime()
            .edit(|core| core.save_snippet_since(id, &opened, &draft))?;
        Ok(match saved {
            aralo_core::Saved::Written(id) => SaveOutcome::Written { id: id.to_string() },
            aralo_core::Saved::Clashed(clash) => SaveOutcome::Clashed {
                clash: SaveClash {
                    disk_text: clash.disk_text,
                    disk: clash.disk.as_ref().map(SnippetDraft::from),
                    mine_text: clash.mine_text,
                    base_text: clash.base_text,
                    clashing_keys: clash.clashes.keys,
                    body_clashes: clash.clashes.body,
                },
            },
        })
    }

    /// Removes a snippet's file. It is unlinked, not put in the trash: a shell
    /// that would rather the user could get it back moves the file itself,
    /// using `snippet()`'s path, and calls `reload()`.
    pub fn delete_snippet(&self, id: String) -> Result<(), BridgeError> {
        let id = snippet_id(&id)?;
        self.shared.runtime().edit(|core| core.delete_snippet(id))?;
        Ok(())
    }

    /// Moves a snippet into another group, keeping its ID.
    pub fn move_snippet(&self, id: String, group: Vec<String>) -> Result<(), BridgeError> {
        let id = snippet_id(&id)?;
        self.shared
            .runtime()
            .edit(|core| core.move_snippet(id, &group))?;
        Ok(())
    }

    pub fn set_snippet_enabled(&self, id: String, enabled: bool) -> Result<(), BridgeError> {
        let id = snippet_id(&id)?;
        self.shared
            .runtime()
            .edit(|core| core.set_snippet_enabled(id, enabled))?;
        Ok(())
    }

    /// Creates an empty group: one folder, and no `_group.yaml` until
    /// something in it is set.
    pub fn create_group(&self, group: Vec<String>) -> Result<(), BridgeError> {
        self.shared
            .runtime()
            .edit(|core| core.create_group(&group))?;
        Ok(())
    }

    /// Renames a group's folder and returns its new path from the root.
    pub fn rename_group(
        &self,
        group: Vec<String>,
        name: String,
    ) -> Result<Vec<String>, BridgeError> {
        Ok(self
            .shared
            .runtime()
            .edit(|core| core.rename_group(&group, &name))?)
    }

    /// Moves a group, and everything in it, inside `into`. An empty `into` is
    /// the library root. Returns its new path.
    pub fn move_group(
        &self,
        group: Vec<String>,
        into: Vec<String>,
    ) -> Result<Vec<String>, BridgeError> {
        Ok(self
            .shared
            .runtime()
            .edit(|core| core.move_group(&group, &into))?)
    }

    /// Removes a group's folder and everything in it, and returns the paths
    /// that went. `group_contents` says how much there is, so a shell can ask
    /// the user first.
    pub fn delete_group(&self, group: Vec<String>) -> Result<Vec<String>, BridgeError> {
        let removed = self
            .shared
            .runtime()
            .edit(|core| core.delete_group(&group))?;
        Ok(removed
            .iter()
            .map(|path| path.to_string_lossy().into_owned())
            .collect())
    }

    /// Switches a group on or off. Off is sticky: nothing inside it expands,
    /// whatever a group further down says.
    pub fn set_group_enabled(&self, group: Vec<String>, enabled: bool) -> Result<(), BridgeError> {
        self.shared
            .runtime()
            .edit(|core| core.set_group_enabled(&group, enabled))?;
        Ok(())
    }

    /// The colour and icon a group is shown with. `None` clears one.
    pub fn set_group_appearance(
        &self,
        group: Vec<String>,
        colour: Option<String>,
        icon: Option<String>,
    ) -> Result<(), BridgeError> {
        self.shared.runtime().edit(|core| {
            core.edit_group(&group, |file| {
                file.colour = colour;
                file.icon = icon;
            })
        })?;
        Ok(())
    }

    /// How many snippets a group holds, counting the groups inside it.
    pub fn group_contents(&self, group: Vec<String>) -> u32 {
        self.shared
            .runtime()
            .read(|core| core.group_contents(&group)) as u32
    }

    /// What the editor should say about a draft before it is saved: blank and
    /// repeated abbreviations, and ones another snippet already answers to.
    /// None of them stops a save.
    ///
    /// `editing` is the snippet on screen, so that its own abbreviations are
    /// not reported as taken by itself. Pass nothing for a new snippet.
    pub fn check_draft(&self, draft: SnippetDraft, editing: Option<String>) -> Vec<DraftProblem> {
        let draft = Draft::from(&draft);
        let editing = editing.and_then(|id| id.parse::<SnippetId>().ok());
        self.shared.runtime().read(|core| {
            core.check_draft(&draft, editing)
                .into_iter()
                .map(DraftProblem::from)
                .collect()
        })
    }

    /// A test field for the draft on screen, as if it were saved in `group`.
    /// Typing into it runs the matcher and the expansion path on the draft as
    /// it stands; nothing is written. `editing` is the snippet on screen, or
    /// nothing for a new one.
    ///
    /// The trial is for this draft. The editor asks for a new one when the
    /// draft changes, and the field starts empty again.
    pub fn try_draft(
        &self,
        draft: SnippetDraft,
        group: Vec<String>,
        editing: Option<String>,
    ) -> Arc<DraftTrial> {
        let draft = Draft::from(&draft);
        let editing = editing.and_then(|id| id.parse::<SnippetId>().ok());
        let trial = self
            .shared
            .runtime()
            .read(|core| core.try_draft(&draft, &group, editing));
        Arc::new(DraftTrial {
            trial: Mutex::new(trial),
            shared: Arc::clone(&self.shared),
        })
    }

    /// An abbreviation for a snippet called `label` that nothing answers to
    /// yet, for the editor to fill the field with. Empty when the label has no
    /// letters in it.
    pub fn suggest_abbreviation(&self, label: String) -> String {
        self.shared
            .runtime()
            .read(|core| core.suggest_abbreviation(&label))
    }

    /// Every snippet matching `query`, best first. An empty query text is the
    /// whole library in list order, so a list and its search box are one call,
    /// and `group` narrows it to whatever the editor's sidebar has selected.
    pub fn search(&self, query: SearchQuery) -> Vec<SearchResult> {
        let mut search = Query::new(query.text);
        search.group = query.group;
        search.tag = query.tag;
        search.enabled_only = query.enabled_only;
        search.kind = query.kind.map(SnippetKind::from);
        if query.limit > 0 {
            search.limit = Some(query.limit as usize);
        }
        self.shared.runtime().read(|core| {
            core.search(&search)
                .into_iter()
                .map(SearchResult::from)
                .collect()
        })
    }

    /// What a snippet expands to, for the editor's preview pane.
    pub fn preview(&self, id: String) -> Option<String> {
        let id = id.parse::<SnippetId>().ok()?;
        self.shared.runtime().read(|core| core.preview(id))
    }

    /// What a body that is still being typed would expand to. The file is not
    /// consulted, so the editor's preview keeps up with the keystroke.
    pub fn preview_draft(&self, body: String) -> String {
        self.shared.runtime().read(|core| core.preview_body(&body))
    }

    /// What the editor draws over the body being typed: where its placeholders
    /// are, and what is wrong with them. The file is not consulted, so it keeps
    /// up with the keystroke, and the ranges are UTF-16 code units, which is
    /// what a text view counts in.
    ///
    /// It is the same parse an expansion runs, so what the editor underlines is
    /// what typing the abbreviation would do (PRD L10).
    pub fn outline_draft(&self, body: String) -> BodyOutline {
        BodyOutline::from(self.shared.runtime().read(|core| core.outline_body(&body)))
    }

    /// Writes dates and times in `tag`, for example `de_DE`. The shell passes
    /// what the operating system says the user reads; a macOS app started from
    /// Finder has no `LANG` for the core to read.
    ///
    /// An unknown tag falls back to the nearest language, then to `en_US`, so
    /// a locale Aralo has no month names for still expands.
    pub fn set_locale(&self, tag: String) {
        self.shared
            .runtime()
            .configure(|core| core.set_locale(&tag));
    }

    /// The locale dates are being written in.
    pub fn locale(&self) -> String {
        self.shared.runtime().read(|core| core.locale().to_owned())
    }

    /// The snippets expanded most recently, most recent first. Empty when
    /// there is no index; `index_problem` says why.
    pub fn recents(&self, limit: u32) -> Vec<String> {
        self.shared
            .runtime()
            .recents(limit as usize)
            .unwrap_or_default()
            .into_iter()
            .map(|recent| recent.id.to_string())
            .collect()
    }

    /// Why there is no search index, when there is none. Recents, usage
    /// counts and search by meaning are what is lost; everything else works
    /// without it.
    pub fn index_problem(&self) -> Option<String> {
        self.shared.runtime().index_error().map(str::to_owned)
    }

    /// Searches by meaning as well as by words, with the embedding model in
    /// `folder`: `tokenizer.json`, `model.safetensors` and `config.json`,
    /// whenever the AI switch in `ai` is on (plan 4.10). The app passes the
    /// model it ships inside itself and its one set of AI settings.
    ///
    /// With AI on, the model loads and the library is embedded in the
    /// background; `search` goes by words until then, and nothing leaves the
    /// machine at any point (PRD A4). With AI off, the model is never loaded,
    /// and switching AI off drops it: the switch is followed from now on,
    /// through `AiProfiles.set_switches` and `reload`.
    pub fn use_model(&self, folder: String, ai: Arc<AiProfiles>) {
        self.shared
            .runtime()
            .use_model(PathBuf::from(&folder), ai.settings());
        *self
            .shared
            .model
            .lock()
            .unwrap_or_else(PoisonError::into_inner) = Some((PathBuf::from(folder), ai));
    }

    /// Why search is going by words alone although a model was given: it
    /// would not load, or there is no index to keep its vectors in.
    pub fn meaning_problem(&self) -> Option<String> {
        self.shared.runtime().meaning_error()
    }

    /// Waits until the background indexer has done everything asked of it so
    /// far: the index caught up, a model loaded, the library embedded. Tests
    /// use it; an app has no reason to wait.
    pub fn wait_for_index(&self) {
        self.shared.runtime().flush();
    }

    /// Reads a file from another expander into the library. A dry run reports
    /// what would happen and writes nothing.
    ///
    /// The report is the answer, not a side effect: an import does not fail
    /// because one snippet did not convert, and the shell shows the report.
    pub fn import(
        &self,
        source: String,
        options: ImportSettings,
    ) -> Result<ImportSummary, BridgeError> {
        let format = match options.format {
            Some(name) => Some(parse_format(&name)?),
            None => None,
        };
        let settings = ImportOptions {
            format,
            into: options.into_group,
            macros: match options.macros {
                MacroHandling::Auto => MacroPolicy::Auto,
                MacroHandling::Convert => MacroPolicy::Convert,
                MacroHandling::Literal => MacroPolicy::Literal,
                MacroHandling::Template => MacroPolicy::Template,
            },
            dry_run: options.dry_run,
        };
        let source = PathBuf::from(source);
        let report = self
            .shared
            .runtime()
            .edit(|core| core.import(&source, &settings))
            .inspect_err(|_| self.shared.counters.error(ErrorKind::ImportFailed))?;
        let mut summary = ImportSummary::from(&report);
        self.shared.count_import(&summary);
        if !summary.dry_run {
            // The library has been read again by now, so every file the import
            // wrote is a snippet with an ID.
            self.shared.runtime().read(|core| {
                let ids: HashMap<&Path, SnippetId> = core
                    .snippets()
                    .iter()
                    .map(|snippet| (snippet.path.as_path(), snippet.id))
                    .collect();
                for entry in &mut summary.entries {
                    entry.id = entry
                        .path
                        .as_deref()
                        .and_then(|path| ids.get(Path::new(path)))
                        .map(ToString::to_string);
                }
            });
        }
        Ok(summary)
    }

    /// The library, or one group of it, as the bytes of an interchange file.
    /// `format` is one of `csv`, `json` or `yaml`.
    pub fn export(&self, format: String, group: Vec<String>) -> Result<Vec<u8>, BridgeError> {
        let options = ExportOptions {
            format: parse_format(&format)?,
            group,
        };
        Ok(self.shared.runtime().read(|core| core.export(&options))?)
    }
}

/// What the shell is told when the library changes underneath it.
///
/// Called on a background thread, with the library read-locked. Hand the event
/// to the main thread and return: the watch reports nothing else until this
/// comes back, and calling back into `Core` from inside it would wait for a
/// lock this call is holding.
#[uniffi::export(with_foreign)]
pub trait CoreEvents: Send + Sync {
    fn library_changed(&self, event: LibraryEvent);
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum LibraryEvent {
    /// Something outside Aralo changed the folder and it has been read again.
    /// The paths are relative to the library root.
    Outside { paths: Vec<String> },
    /// Aralo changed the folder, through one of the editing calls.
    Edited,
    /// The folder was read again because `reload` asked for it.
    Reloaded,
    /// The folder changed and reading it failed. The library in memory is the
    /// last one that loaded, and expansion carries on with it.
    Failed { message: String },
    /// Conflict copies a sync client left were merged into their originals and
    /// discarded. The paths are the copies', relative to the library root.
    Merged { copies: Vec<String> },
    /// The search index caught up with the library.
    Indexed {
        added: u32,
        updated: u32,
        removed: u32,
    },
}

/// A snippet's fields as a person edits them. `None` means "inherit from the
/// group", which is not the same as the value the group resolves to today.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct SnippetDraft {
    pub label: String,
    pub abbreviations: Vec<String>,
    pub body: String,
    pub tags: Vec<String>,
    pub kind: SnippetType,
    pub trigger: Option<Trigger>,
    pub case: Option<CaseStyle>,
    /// Expand only after a non-word character.
    pub whole_word: Option<bool>,
    /// Re-insert the delimiter that triggered the expansion.
    pub keep_delimiter: Option<bool>,
    pub enabled: Option<bool>,
}

/// One snippet as the editor shows it.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct SnippetDetail {
    pub id: String,
    /// Path from the library root.
    pub path: String,
    pub group: Vec<String>,
    pub draft: SnippetDraft,
    /// What the draft's `None`s come to once the groups above it are applied.
    pub resolved: ResolvedSettings,
    /// What typing the abbreviation would produce.
    pub preview: String,
}

/// How a snippet behaves with every level of inheritance applied.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Record)]
pub struct ResolvedSettings {
    pub trigger: Trigger,
    pub case: CaseStyle,
    pub whole_word: bool,
    pub keep_delimiter: bool,
    /// False when the snippet or any group above it is switched off.
    pub enabled: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum SnippetType {
    Text,
    Rich,
    Command,
    Prompt,
    Script,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum Trigger {
    /// Expand the moment the abbreviation is complete.
    Immediate,
    /// Expand when a delimiter follows it.
    Delimiter,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum CaseStyle {
    /// Only an exact match expands.
    Exact,
    /// Case is ignored, and the snippet expands as it is written.
    Ignore,
    /// Case is ignored, and the expansion follows how it was typed.
    Adaptive,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct GroupSummary {
    /// Folder names from the library root down. Empty for the root itself.
    pub path: Vec<String>,
    pub name: String,
    pub colour: Option<String>,
    pub icon: Option<String>,
    pub enabled: bool,
    /// Snippets directly in this group, not counting its sub-groups.
    pub snippets: u32,
}

/// Something the editor should say about a draft. None of these stops a save.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct DraftProblem {
    /// Which abbreviation it is about, when it is about one.
    pub abbreviation: Option<String>,
    pub message: String,
    /// The snippet that already answers to this abbreviation, if that is the
    /// problem. The editor offers to show it.
    pub conflicts_with: Option<String>,
}

/// What the snippet list is asking for: the search box, and the filters the
/// sidebar sets. Every field empty is the whole library in list order.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct SearchQuery {
    /// What the user typed. Empty matches everything.
    pub text: String,
    /// Only snippets in this group or in a group inside it. `None` is the
    /// whole library; an empty path is the root, which is the same thing.
    pub group: Option<Vec<String>>,
    /// Only snippets carrying this tag, compared without case.
    pub tag: Option<String>,
    /// Leave out snippets that are switched off, here or by a group above them.
    pub enabled_only: bool,
    /// At most this many hits, after ranking. Zero is no limit.
    pub limit: u32,
    /// Only snippets of this type. The palette asks for `Text`: a command
    /// runs on a selection and has nothing to insert.
    #[uniffi(default = None)]
    pub kind: Option<SnippetType>,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct SearchResult {
    pub id: String,
    pub name: String,
    pub abbreviations: Vec<String>,
    pub group: Vec<String>,
    pub enabled: bool,
    /// Which field matched: the row shows this text with `matched` highlighted.
    pub field: SearchField,
    pub text: String,
    /// Character offsets into `text` that matched, in order.
    pub matched: Vec<u32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum SearchField {
    Abbreviation,
    Label,
    Body,
    Tag,
    Group,
    /// No word of the query, but what it means. `text` is the body's first
    /// line and nothing in it is highlighted.
    Meaning,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct ImportSettings {
    /// `textexpander`, `csv`, `json` or `yaml`. Nothing asks Aralo to work it
    /// out from the file.
    pub format: Option<String>,
    /// Put everything under this group, above whatever group the source gives.
    pub into_group: Vec<String>,
    pub macros: MacroHandling,
    /// Work out what would happen and write nothing.
    pub dry_run: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum MacroHandling {
    /// Convert the source's macros where the body plainly carries them.
    Auto,
    /// Convert, even where the macros are only a maybe.
    Convert,
    /// Never convert: the body is literal text.
    Literal,
    /// The body is an Aralo template already.
    Template,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct ImportSummary {
    pub format: String,
    pub dry_run: bool,
    pub total: u32,
    /// Imported, or that would have been.
    pub imported: u32,
    /// Imported, and expands, but something in it needs a human.
    pub needs_edit: u32,
    pub skipped: u32,
    /// The share that converts with no manual edit, from 0 to 1.
    pub fidelity: f64,
    pub entries: Vec<ImportedSnippet>,
    /// The report as the command line prints it, for a window that shows it.
    pub report: String,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct ImportedSnippet {
    pub label: String,
    pub abbreviations: Vec<String>,
    pub group: Vec<String>,
    /// Path from the library root, when one was written.
    pub path: Option<String>,
    /// The snippet it became, for a report that opens it in the editor. `None`
    /// on a dry run and for anything skipped.
    pub id: Option<String>,
    pub outcome: ImportOutcome,
    pub notes: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum ImportOutcome {
    /// Imported with nothing lost.
    Clean,
    /// Imported, and it will expand, but the notes say what needs a human.
    NeedsEdit,
    /// Not imported.
    Skipped,
}

/// What an editor draws over a body: where the placeholders are, and what it
/// should say about them.
///
/// Every range is in UTF-16 code units from the start of the body, which is
/// what `NSTextView` and every other text view Aralo drives counts in, so a
/// shell converts nothing.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct BodyOutline {
    /// Every `{{…}}` the core read, in the order they appear.
    pub placeholders: Vec<BodyPlaceholder>,
    /// What to show under the body, in the order the problems appear. Empty for
    /// a body that expands as it reads.
    pub problems: Vec<BodyProblem>,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct BodyPlaceholder {
    pub name: String,
    /// False when no placeholder has this name. It still parses, so this marks
    /// one to point at, not a broken one; `problems` carries the note.
    pub known: bool,
    /// False while the core does not expand this name yet, in which case it
    /// inserts as the text it is written as.
    pub evaluated: bool,
    pub start: u32,
    pub end: u32,
}

/// Something for the editor to show under a range of the body.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct BodyProblem {
    pub level: DiagnosticLevel,
    /// One sentence, in the core's words.
    pub message: String,
    pub start: u32,
    pub end: u32,
}

/// One placeholder an editor's insert menu offers.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct PlaceholderChoice {
    pub name: String,
    /// One line for the menu item.
    pub summary: String,
    /// The text to insert at the caret.
    pub insert: String,
    /// What to select inside `insert` once it is in, in UTF-16 code units from
    /// its start: the part the user replaces with their own words. Equal
    /// offsets select nothing and leave the caret after the insertion.
    pub select_start: u32,
    pub select_end: u32,
    /// False while the core does not expand it yet, in which case it inserts as
    /// the text it is written as.
    pub evaluated: bool,
}

const PREVIEW_CHARS: usize = 120;

/// What `Core::move_library` did.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct LibraryMove {
    pub from: String,
    pub to: String,
    pub files: u32,
    pub snippets: u32,
    /// Files in the old folder that changed after they were copied, or that
    /// could not be read to tell. While there are any, the old folder holds
    /// something the new one does not, and it is not moved to the Trash.
    pub changed_after_copy: Vec<String>,
    /// Why the counts and recents did not come along, when they did not.
    pub index_problem: Option<String>,
}

/// What is at a folder the user picked for the library.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct LibraryLocation {
    pub path: String,
    /// The sync client that looks after the folder, in its own words
    /// ("iCloud Drive", "Dropbox"), when its path says so.
    pub provider: Option<String>,
    pub contents: LocationContents,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum LocationContents {
    /// Nothing there: the library can be moved here.
    Empty,
    /// A library already, which can be used as it is.
    Library { snippets: u32 },
    /// Other files: neither a move nor a switch goes here.
    Occupied,
}

/// What is at `path`, for the library picker to say what choosing it would
/// do before anything is done.
#[uniffi::export]
pub fn inspect_library_location(path: String) -> LibraryLocation {
    let location = aralo_core::relocate::inspect(Path::new(&path));
    LibraryLocation {
        path,
        provider: location.provider.map(|provider| provider.name().to_owned()),
        contents: match location.contents {
            aralo_core::Contents::Empty => LocationContents::Empty,
            aralo_core::Contents::Library { snippets } => LocationContents::Library {
                snippets: snippets as u32,
            },
            aralo_core::Contents::Occupied => LocationContents::Occupied,
        },
    }
}

/// The version of the Rust core, for the About window and bug reports.
#[uniffi::export]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_owned()
}

/// Apps Aralo stays out of without being told to, for the settings window.
#[uniffi::export]
pub fn excluded_app_presets() -> Vec<String> {
    matcher::EXCLUDED_APP_PRESETS
        .iter()
        .map(|id| (*id).to_owned())
        .collect()
}

/// Every placeholder the format defines, in the order a menu offers them. The
/// list is the core's, so a second shell offers the same placeholders in the
/// same words.
#[uniffi::export]
pub fn placeholder_choices() -> Vec<PlaceholderChoice> {
    aralo_core::Core::placeholders()
        .iter()
        .map(PlaceholderChoice::from)
        .collect()
}

/// The apps a compatibility table names, in file order: the table built into
/// the core, or the file at `path`. The injection matrix walks this list, so
/// it tests the apps the table makes claims about.
#[uniffi::export]
pub fn compat_apps(path: Option<String>) -> Result<Vec<CompatApp>, BridgeError> {
    let table = match path {
        Some(path) => read_compat_table(&path)?,
        None => CompatTable::bundled(),
    };
    Ok(table
        .apps()
        .iter()
        .map(|app| CompatApp {
            name: app.name.clone(),
            bundle_id: app.bundle_id.clone(),
            profile: app.profile.into(),
        })
        .collect())
}

fn read_compat_table(path: &str) -> Result<CompatTable, BridgeError> {
    let text = std::fs::read_to_string(path).map_err(|error| BridgeError::CompatTable {
        message: format!("cannot read {path}: {error}"),
    })?;
    CompatTable::parse(&text).map_err(|error| BridgeError::CompatTable {
        message: format!("{path}: {error}"),
    })
}

impl From<compat::InjectionProfile> for InjectionProfile {
    fn from(profile: compat::InjectionProfile) -> Self {
        Self {
            insert: match profile.insert {
                compat::InsertChoice::Auto => InsertChoice::Auto,
                compat::InsertChoice::Type => InsertChoice::Type,
                compat::InsertChoice::Paste => InsertChoice::Paste,
            },
            typing_limit: profile.typing_limit,
            key_delay_ms: profile.key_delay_ms,
            paste_settle_ms: profile.paste_settle_ms,
            undo: match profile.undo {
                compat::UndoStyle::Native => UndoStyle::Native,
                compat::UndoStyle::Backspace => UndoStyle::Backspace,
            },
            delete: match profile.delete {
                compat::DeleteStrategy::Backspace => DeleteStrategy::Backspace,
                compat::DeleteStrategy::Select => DeleteStrategy::Select,
            },
        }
    }
}

impl From<Step> for PlanStep {
    fn from(step: Step) -> Self {
        match step {
            Step::Delete { count } => PlanStep::Delete { count },
            Step::InsertText { text } => PlanStep::InsertText { text },
            Step::InsertRich { html, plain } => PlanStep::InsertRich { html, plain },
            Step::KeyPress { key } => PlanStep::KeyPress {
                key: match key {
                    aralo_core::Key::Return => PlanKey::Return,
                    aralo_core::Key::Tab => PlanKey::Tab,
                },
            },
            Step::Delay { millis } => PlanStep::Delay { millis },
            Step::MoveCursor { graphemes, select } => PlanStep::MoveCursor { graphemes, select },
        }
    }
}

impl From<PlanStep> for Step {
    fn from(step: PlanStep) -> Self {
        match step {
            PlanStep::Delete { count } => Step::Delete { count },
            PlanStep::InsertText { text } => Step::InsertText { text },
            PlanStep::InsertRich { html, plain } => Step::InsertRich { html, plain },
            PlanStep::KeyPress { key } => Step::KeyPress {
                key: match key {
                    PlanKey::Return => aralo_core::Key::Return,
                    PlanKey::Tab => aralo_core::Key::Tab,
                },
            },
            PlanStep::Delay { millis } => Step::Delay { millis },
            PlanStep::MoveCursor { graphemes, select } => Step::MoveCursor { graphemes, select },
        }
    }
}

fn summarise(snippet: &aralo_core::LoadedSnippet) -> SnippetSummary {
    SnippetSummary {
        id: snippet.id.to_string(),
        label: snippet.file.front.label.clone(),
        abbreviations: snippet.file.front.abbr.clone(),
        group: snippet.group.clone(),
        path: snippet.path.to_string_lossy().into_owned(),
        enabled: snippet.settings.enabled,
        preview: snippet.file.body.chars().take(PREVIEW_CHARS).collect(),
    }
}

/// An ID the shell handed back. Anything but one Aralo gave it is a bug in the
/// shell, so it reads as "no such snippet" rather than as a crash.
fn snippet_id(text: &str) -> Result<SnippetId, BridgeError> {
    text.parse::<SnippetId>().map_err(|_| BridgeError::Library {
        message: format!("no snippet with the id {text} is in the library"),
    })
}

fn parse_format(name: &str) -> Result<Format, BridgeError> {
    name.parse::<Format>().map_err(|error| BridgeError::Import {
        message: error.to_string(),
    })
}

impl From<LibraryChange> for LibraryEvent {
    fn from(change: LibraryChange) -> Self {
        match change {
            LibraryChange::Outside { paths } => LibraryEvent::Outside {
                paths: paths
                    .iter()
                    .map(|path| path.to_string_lossy().into_owned())
                    .collect(),
            },
            LibraryChange::Edited => LibraryEvent::Edited,
            LibraryChange::Reloaded => LibraryEvent::Reloaded,
            LibraryChange::Failed { message } => LibraryEvent::Failed { message },
            LibraryChange::Merged { copies } => LibraryEvent::Merged {
                copies: copies
                    .iter()
                    .map(|path| path.to_string_lossy().into_owned())
                    .collect(),
            },
            LibraryChange::Indexed {
                added,
                updated,
                removed,
            } => LibraryEvent::Indexed {
                added: added as u32,
                updated: updated as u32,
                removed: removed as u32,
            },
        }
    }
}

