impl From<aralo_core::DraftIssue> for DraftProblem {
    fn from(issue: aralo_core::DraftIssue) -> Self {
        use aralo_core::Problem;
        let (message, conflicts_with) = match issue.problem {
            Problem::Blank => (
                "An abbreviation of only spaces can never be typed.".to_owned(),
                None,
            ),
            Problem::Taken { by, name, path } => (
                format!(
                    "“{name}” already answers to this, in {}. Only one of the two will expand.",
                    path.display()
                ),
                Some(by.to_string()),
            ),
            Problem::Repeated => ("The same abbreviation twice.".to_owned(), None),
            Problem::UnsupportedKind(kind) => (
                format!("{kind:?} snippets do not expand in this version yet."),
                None,
            ),
        };
        Self {
            abbreviation: issue.abbr,
            message,
            conflicts_with,
        }
    }
}

impl From<aralo_core::SearchHit> for SearchResult {
    fn from(hit: aralo_core::SearchHit) -> Self {
        use aralo_core::Field;
        Self {
            id: hit.id.to_string(),
            name: hit.name,
            abbreviations: hit.abbr,
            group: hit.group,
            enabled: hit.enabled,
            field: match hit.field {
                Field::Abbreviation => SearchField::Abbreviation,
                Field::Label => SearchField::Label,
                Field::Body => SearchField::Body,
                Field::Tag => SearchField::Tag,
                Field::Group => SearchField::Group,
                Field::Meaning => SearchField::Meaning,
            },
            text: hit.text,
            matched: hit.matched,
        }
    }
}

impl From<&ImportReport> for ImportSummary {
    fn from(report: &ImportReport) -> Self {
        Self {
            format: report.format.to_string(),
            dry_run: report.dry_run,
            total: report.total() as u32,
            imported: report.imported() as u32,
            needs_edit: report.count(Outcome::NeedsEdit) as u32,
            skipped: report.count(Outcome::Skipped) as u32,
            fidelity: report.fidelity(),
            entries: report
                .entries
                .iter()
                .map(|entry| ImportedSnippet {
                    label: entry.label.clone(),
                    abbreviations: entry.abbr.clone(),
                    group: entry.group.clone(),
                    path: entry
                        .path
                        .as_ref()
                        .map(|path| path.to_string_lossy().into_owned()),
                    id: None,
                    outcome: match entry.outcome {
                        Outcome::Clean => ImportOutcome::Clean,
                        Outcome::NeedsEdit => ImportOutcome::NeedsEdit,
                        Outcome::Skipped => ImportOutcome::Skipped,
                    },
                    notes: entry.notes.iter().map(|note| note.detail.clone()).collect(),
                })
                .collect(),
            report: report.to_string(),
        }
    }
}

impl From<aralo_core::BodyOutline> for BodyOutline {
    fn from(outline: aralo_core::BodyOutline) -> Self {
        Self {
            placeholders: outline
                .placeholders
                .into_iter()
                .map(|placeholder| BodyPlaceholder {
                    name: placeholder.name,
                    known: placeholder.known,
                    evaluated: placeholder.evaluated,
                    start: placeholder.range.start,
                    end: placeholder.range.end,
                })
                .collect(),
            problems: outline
                .problems
                .into_iter()
                .map(|problem| BodyProblem {
                    level: match problem.level {
                        aralo_core::ProblemLevel::Error => DiagnosticLevel::Error,
                        aralo_core::ProblemLevel::Note => DiagnosticLevel::Note,
                    },
                    message: problem.message,
                    start: problem.range.start,
                    end: problem.range.end,
                })
                .collect(),
        }
    }
}

impl From<&aralo_core::PlaceholderInfo> for PlaceholderChoice {
    fn from(info: &aralo_core::PlaceholderInfo) -> Self {
        Self {
            name: info.name.to_owned(),
            summary: info.summary.to_owned(),
            insert: info.insert.to_owned(),
            select_start: info.select.start,
            select_end: info.select.end,
            evaluated: info.evaluated,
        }
    }
}

fn describe(issue: &aralo_core::Issue) -> (DiagnosticLevel, String) {
    use aralo_core::Issue;
    use DiagnosticLevel::{Error, Note, Warning};
    match issue {
        Issue::Unreadable(why) => (Error, format!("Cannot be read: {why}")),
        Issue::Invalid(why) => (Error, why.clone()),
        Issue::TooLarge { bytes } => (Error, format!("{bytes} bytes is too large for a snippet.")),
        Issue::DuplicateId { first } => (
            Error,
            format!(
                "Has the same id as {}, so this file is ignored.",
                first.display()
            ),
        ),
        Issue::ConflictCopy { original } => (
            Warning,
            format!(
                "A sync conflict copy of {} that changes the same things differently. Choose which to keep.",
                original.display()
            ),
        ),
        Issue::AbbreviationRejected {
            abbreviation,
            reason,
        } => (
            Error,
            format!("The abbreviation “{abbreviation}” cannot be used: {reason}."),
        ),
        Issue::TooDeep => (
            Error,
            "Folders are nested too deeply; not loaded.".to_owned(),
        ),
        Issue::SymlinkedFolder => (
            Warning,
            "Symbolic links to folders are not followed.".to_owned(),
        ),
        Issue::NotDownloaded => (
            Warning,
            "In iCloud Drive but not downloaded to this Mac. It loads once it is.".to_owned(),
        ),
        Issue::UnsupportedKind(kind) => (
            Warning,
            format!("{kind:?} snippets do not expand in this version yet."),
        ),
        Issue::MissingId => (
            Note,
            "Has no id yet; Aralo adds one when it saves the file.".to_owned(),
        ),
        Issue::NotASnippet => (Note, "No front matter, so not a snippet.".to_owned()),
    }
}
